CREATE TABLE `geo_comuni` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `geo_provincia_id` bigint unsigned NOT NULL,
  `codice_istat` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nome` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `logo` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `logo_citta` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `lat` decimal(10,7) DEFAULT NULL,
  `lng` decimal(10,7) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `geo_comuni_codice_istat_unique` (`codice_istat`),
  KEY `geo_comuni_geo_provincia_id_index` (`geo_provincia_id`),
  KEY `geo_comuni_nome_index` (`nome`),
  CONSTRAINT `geo_comuni_geo_provincia_id_foreign` FOREIGN KEY (`geo_provincia_id`) REFERENCES `geo_province` (`id`) ON DELETE CASCADE
