CREATE TABLE `geo_province` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `geo_regione_id` bigint unsigned NOT NULL,
  `sigla` varchar(3) COLLATE utf8mb4_unicode_ci NOT NULL,
