  `codice_provincia` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `geo_province_sigla_unique` (`sigla`),
  KEY `geo_province_geo_regione_id_index` (`geo_regione_id`),
