DROP TABLE IF EXISTS `users`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `users` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `email` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `email_verified_at` timestamp NULL DEFAULT NULL,
  `password` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `ruolo` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'struttura_user',
  `struttura_id` bigint unsigned DEFAULT NULL,
  `proprietario_id` bigint unsigned DEFAULT NULL,
  `avatar` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `remember_token` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `users_email_unique` (`email`),
  KEY `users_struttura_id_index` (`struttura_id`),
  KEY `users_proprietario_id_index` (`proprietario_id`),
  CONSTRAINT `users_proprietario_id_foreign` FOREIGN KEY (`proprietario_id`) REFERENCES `proprietari` (`id`) ON DELETE SET NULL,
  CONSTRAINT `users_struttura_id_foreign` FOREIGN KEY (`struttura_id`) REFERENCES `struttura` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
